function elements(node) {
  return [...(node.tagName ? [node] : []), ...(node.childNodes ?? []).flatMap(elements)];
}

function attribute(node, name) {
  return node.attrs?.find(item => item.name === name)?.value;
}

function textContent(node) {
  return node.value ?? (node.childNodes ?? []).map(textContent).join('');
}

export function compileVisualLessons() {
  const postSlugs = readdirSync(join(root, 'src/content/posts')).filter(filename => filename.endsWith('.md')).map(filename => filename.replace(/^\d{4}-\d{2}-\d{2}-/, '').replace(/\.md$/, '')).sort();
  assert.deepEqual(Object.keys(lessonPlans).sort(), postSlugs, 'Every source post needs exactly one authored visual lesson');
  const lessons = {};
  const scenes = {};
  for (const [slug, plan] of Object.entries(lessonPlans)) {
    const audit = JSON.parse(readFileSync(join(root, 'data/visual-audits', `${slug}.json`), 'utf8'));
    const source = readFileSync(join(root, audit.article), 'utf8');
    const available = [];
    function visit(node) {
      if (node.type === 'html') {
        for (const figure of elements(parseFragment(node.value)).filter(element => element.tagName === 'figure')) {
          const primary = elements(figure).find(element => attribute(element, 'data-visual-argument'));
          if (!primary) continue;
          const identity = attribute(primary, 'data-visual-argument');
          const frames = elements(figure).filter(element => attribute(element, 'data-frame-key') !== undefined).length;
          available.push(`${identity}: mechanism${frames ? ` and ${frames} trace checkpoints` : ' and retained detailed drawing'}`);
        }
      }
      for (const child of node.children ?? []) visit(child);
    }
    visit(fromMarkdown(source));
    assert(plan.steps.length && plan.missing && plan.decision, slug);
    lessons[slug] = { idea: plan.idea ?? audit.learningObjective, steps: plan.steps, review: { available: available.join('; '), missing: plan.missing, decision: plan.decision } };
    for (const step of plan.steps) {
      for (const visualId of [step.visualId, ...(step.printPanels ?? [])]) {
        if (lessonScenes[visualId] && !scenes[visualId]) {
          const html = renderLessonScene(visualId);
          scenes[visualId] = { html, sha256: createHash('sha256').update(html).digest('hex') };
        }
      }
    }
  }
  return { catalog: { schemaVersion: 1, lessons }, artwork: { schemaVersion: 1, scenes } };
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  const { catalog, artwork } = compileVisualLessons();
  for (const [filename, value] of [['visual-lessons.json', catalog], ['visual-lesson-artwork.json', artwork]]) {
    const destination = join(root, 'data', filename);
    const content = `${JSON.stringify(value, null, 2)}\n`;
    if (process.argv.includes('--write')) writeFileSync(destination, content);
    else assert.equal(readFileSync(destination, 'utf8'), content, `${filename}: generated visual lessons are stale`);
  }
  console.log(`Visual lessons ${process.argv.includes('--write') ? 'generated' : 'verified'}: ${Object.keys(catalog.lessons).length} reviewed posts, ${Object.keys(artwork.scenes).length} purpose-built assets.`);
}